class Solution {
    unordered_map<Node*, NodeCopy*> clones;

    NodeCopy* copyStructure(Node* node) {
        if (!node) {
            return nullptr;
        }
        NodeCopy* result = new NodeCopy(node->val);
        clones[node] = result;
        result->left = copyStructure(node->left);
        result->right = copyStructure(node->right);
        return result;
    }

    void copyRandom(Node* node) {
        if (!node) {
            return;
        }
        clones[node]->random = node->random ? clones[node->random] : nullptr;
        copyRandom(node->left);
        copyRandom(node->right);
    }

public:
    NodeCopy* copyRandomBinaryTree(Node* root) {
        clones.clear();
        NodeCopy* result = copyStructure(root);
        copyRandom(root);
        return result;
    }
};
